def predecessor(name,text):
    if name not in SPECS:raise RuntimeError("unknown normal cleanup source")
    current_n,current_sha,prior_n,prior_sha,spans=SPECS[name]
    raw=text.encode("utf-8");actual_sha=sha256(raw).hexdigest()
    if len(raw)==prior_n and actual_sha==prior_sha:
        return text,{"applied":False,"source_sha256":prior_sha,"proof_only":True}
    if len(raw)!=current_n or actual_sha!=current_sha:
        raise RuntimeError("unreviewed normal cleanup whole source: "+name)
    for start,end,expected,previous in reversed(spans):
        if not(0<=start<=end<=len(raw)) or sha256(raw[start:end]).hexdigest()!=expected:
            raise RuntimeError("normal cleanup exact inverse span differs: "+name)
        raw=raw[:start]+previous+raw[end:]
    if len(raw)!=prior_n or sha256(raw).hexdigest()!=prior_sha:
        raise RuntimeError("normal cleanup inverse does not restore complete f4c0 source: "+name)
    return raw.decode("utf-8"),{"applied":True,"actual_bytes":current_n,"actual_sha256":actual_sha,
        "restored_bytes":prior_n,"restored_sha256":prior_sha,"exact_spans":len(spans),
        "proof_only":True,"actual_compilation_uses_current_source":True}
